const body = $input.first().json.body || $input.first().json;
let lotId = (body.lot_id || '').trim();
lotId = lotId.replace(/[^A-Za-z0-9_-]/g, '');
return { json: { lot_id: lotId } };

const rows = $input.first().json || [];
const arr = Array.isArray(rows) ? rows : [rows];
const info = arr[0] || null;
let text = '';
if (!info) {
  text = '未找到 Lot: ' + ($input.first().json.lot_id || '');
} else {
  text = `Lot: ${info.lot_id || ''}\n产品: ${info.product_id || '未知'}\n当前站: ${info.current_step || '未知'}\n状态: ${info.status || '未知'}\n晶圆数: ${info.wafer_qty || 0}`;
}
return { json: { lot_info: info, summary: text } };
